let grades=read('studyflow.grades.v1',[]);
if(!Array.isArray(grades))grades=[];
const account=globalThis.studyAccount;
let sync={revision:0,dirty:false,busy:false,status:'Checking account…',conflict:null,generation:0,loaded:false};
let authConfig={googleClientId:null},recoveryCode='',authBusy=false,editGradeId=null;
const canonical='https://studyflow.apencilgod181.workers.dev';
const isStaticMirror=location.hostname?.endsWith('.chatgpt.site');
async function requestAPI(path,options={}){const response=await fetch('/api/'+path,{credentials:'same-origin',...options,headers:{'Content-Type':'application/json',...(account.user&&['plan','logout','delete-account'].includes(path)?{'X-StudyFlow-Account':account.user.id}:{}),...options.headers}});let data;try{data=await response.json();}catch{throw new Error('Account services are available on the Cloudflare website.');}if(!response.ok)throw Object.assign(new Error(data.error||'Unable to connect. Please try again.'),{status:response.status});return data;}
function localKey(key){return account.user?'studyflow.user.'+account.user.id+'.'+key:key;}
function writeLocal(key,value){try{localStorage.setItem(localKey(key),JSON.stringify(value));}catch{storageError=true;}}
function snapshot(){return {assignments:structuredClone(assignments),grades:structuredClone(grades),budget};}
function cachePlan(){writeLocal('studyflow.assignments.v1',assignments);writeLocal('studyflow.budget.v1',budget);writeLocal('studyflow.grades.v1',grades);if(account.user)writeLocal('pending',{data:snapshot(),revision:sync.revision,dirty:sync.dirty});}
function applyPlan(data){assignments=data?.assignments||[];grades=data?.grades||[];budget=data?.budget||90;cachePlan();}
function updateAccountStatus(){const status=$('#account-status');if(!status)return;status.innerHTML=account.user?`<a href="#account" class="account-link"><span class="status-dot"></span><span id="sync-label">${esc(sync.status)}</span><span class="avatar">${esc(account.user.name.slice(0,1).toUpperCase())}</span></a>`:`<a href="#login" class="text-button">Log in</a><a href="#signup" class="button small">Sign up <span>↗</span></a>`;const badge=$('.local-badge');if(badge)badge.textContent=account.user?'⌁  '+sync.status:'⌁  Saved on this device';}
globalThis.studySyncChanged=()=>{if(!account.user||!sync.loaded)return;sync.dirty=true;sync.generation++;sync.status='Unsynced changes';cachePlan();updateAccountStatus();clearTimeout(sync.timeout);sync.timeout=setTimeout(()=>pushPlan(),650);};
async function pushPlan(){if(!account.user||!sync.loaded||!sync.dirty||sync.busy||sync.conflict)return;sync.busy=true;const generation=sync.generation;const userId=account.user.id;sync.status='Saving…';updateAccountStatus();try{const result=await requestAPI('plan',{method:'PUT',body:JSON.stringify({data:snapshot(),revision:sync.revision})});if(account.user?.id!==userId)return;sync.revision=result.revision;sync.dirty=generation!==sync.generation;sync.status=sync.dirty?'Unsynced changes':'All changes synced';cachePlan();}catch(error){if(account.user?.id!==userId)return;if(error.status===409){sync.conflict=true;sync.status='Sync needs your choice';toast('Another device changed your plan. Open My account to resolve it.');}else{sync.status=error.status===401?'Session expired · Sign in':error.status?'Sync paused · '+error.message:'Offline · Changes saved here';}}finally{sync.busy=false;updateAccountStatus();if(page==='account')render();if(sync.dirty&&!sync.conflict&&sync.status==='Unsynced changes')pushPlan();}}
async function pullPlan(){if(!account.user||!sync.loaded||sync.busy||sync.dirty||sync.conflict)return;sync.busy=true;const id=account.user.id;try{const result=await requestAPI('plan');if(account.user?.id!==id)return;if(result.revision!==sync.revision&&!sync.dirty){sync.revision=result.revision;applyPlan(result.data);render();}sync.status='All changes synced';}catch(error){sync.status=error.status===401?'Session expired · Sign in':'Offline · Your last synced plan';}finally{sync.busy=false;updateAccountStatus();}}
async function enterAccount(user,{newAccount=false}={}){account.user=user;sync={revision:0,dirty:false,busy:false,status:'Loading your plan…',conflict:null,generation:0,loaded:false};updateAccountStatus();const pending=read(localKey('pending'),null);try{const result=await requestAPI('plan');sync.revision=result.revision;if(pending?.dirty&&pending.data){sync.revision=pending.revision;applyPlan(pending.data);sync.dirty=true;sync.conflict=result.revision!==pending.revision;sync.status=sync.conflict?'Sync needs your choice':'Unsynced changes';cachePlan();}else if(result.data){applyPlan(result.data);sync.status='All changes synced';}else{applyPlan({assignments:[],grades:[],budget:90});sync.status='All changes synced';}sync.loaded=true;account.ready=true;location.hash=newAccount&&!recoveryCode&&typeof setupPreferences==='function'&&!setupPreferences()?'#setup':'#account';render();if(sync.dirty&&!sync.conflict)await pushPlan();if(newAccount)toast('Your account is ready. Bring your plan along.');}catch(error){sync.status='Unable to load · Retry sync';sync.loaded=false;assignments=[];grades=[];budget=90;render();throw error;}}
function authPage(){const signup=page==='signup',recover=page==='recover';if(isStaticMirror)return heading('YOUR ACCOUNT','Take StudyFlow with you.','Accounts and syncing are available on the Cloudflare website.')+`<section class="card"><h2>Your connected study space</h2><p class="muted">Log in or create an account on the main website to sync across devices. Plans saved on this preview stay in this browser.</p><a class="button" href="${canonical}/#${page}">Continue to StudyFlow ↗</a></section>`;return `<div class="auth-layout"><section class="auth-story"><a class="brand" href="#dashboard"><span class="brand-icon">≋</span> StudyFlow.</a><p class="eyebrow">A LITTLE STRUCTURE. MORE HEADSPACE.</p><h1>Your progress,<br>wherever you go.</h1><p>Your assignments, study plan, and grades.<br>One calm space that comes with you.</p><div class="auth-art" aria-hidden="true"><div class="auth-paper"><span>YOUR NEXT LITTLE WIN</span><div>✓ &nbsp; One task at a time</div><div>✓ &nbsp; Room to breathe</div><div>✓ &nbsp; A plan that fits you</div></div><span class="auth-star">✧</span></div><p class="muted">Make room for a good day.</p></section><section class="card auth-card"><a href="#dashboard" class="text-button">← Back to your planner</a><p class="eyebrow" style="margin-top:30px">${recover?'A FRESH START':signup?'YOUR NEXT CHAPTER':'GOOD TO HAVE YOU BACK'}</p><h2>${recover?'Recover your account':signup?'Create your account':'Welcome back.'}</h2><p class="muted">${recover?'Use the recovery code you saved when you signed up.':signup?'A little organization that follows you everywhere.':'Pick up right where you left off.'}</p>${!recover?'<div id="google-button" class="google-slot"></div><p id="google-message" class="muted"></p><div class="auth-divider"><span>or continue with email</span></div>':''}<form id="auth-form">${signup?'<label>Your name<input name="name" autocomplete="given-name" maxlength="60" required placeholder="What should we call you?"></label>':''}<label>Email address<input name="email" type="email" autocomplete="email" maxlength="254" required placeholder="you@example.com"></label>${recover?'<label>Recovery code<input name="recoveryCode" autocomplete="off" required placeholder="Your saved recovery code"></label>':''}<label>${recover?'New password':'Password'}<div class="password-wrap"><input name="password" id="auth-password" type="password" autocomplete="${signup||recover?'new-password':'current-password'}" minlength="12" maxlength="128" required placeholder="${signup||recover?'At least 12 characters':'Enter your password'}"><button type="button" class="text-button" id="show-password" aria-label="Show password">Show</button></div></label>${signup||recover?'<label>Confirm password<input name="confirm" type="password" autocomplete="new-password" minlength="12" maxlength="128" required placeholder="Enter your password again"></label>':'<a href="#recover" class="text-button">Forgot password?</a>'}<p id="auth-error" role="alert" class="form-error"></p><button class="button" type="submit" ${!account.ready||authBusy?'disabled':''}>${authBusy?'Just a moment…':recover?'Reset password':signup?'Create account':'Log in'} <span>↗</span></button></form><p class="auth-switch">${signup?'Already have an account?':'New to StudyFlow?'} <a href="#${signup?'login':'signup'}">${signup?'Log in':'Create an account'}</a></p><div class="auth-privacy">${signup?'Your email, assignments, and grades are stored in your private account on Cloudflare. Practice notes stay in this tab. A recovery code replaces email password resets.':'Your plan is private to your account. You can also keep using StudyFlow without signing in.'}</div></section></div>`;}
function accountPage(){if(!account.user)return heading('YOUR STUDY SPACE, EVERYWHERE','A little progress. Always with you.','Sign in to sync your assignments, progress, and grades across devices.')+`<section class="card account-welcome"><span class="focus-icon">⌁</span><h2>Make yourself at home.</h2><p class="muted">Your current plan is saved on this device. Create an account to bring your work with you, or log in to pick up an existing plan.</p><div class="timer-controls"><a class="button" href="#signup">Create an account ↗</a><a class="button secondary" href="#login">Log in</a></div></section>`;return heading('YOUR ACCOUNT','Your space, connected.','Keep your progress close, wherever you study.')+`${recoveryCode?`<section class="notice"><strong>Save your recovery code</strong><p>Keep this somewhere safe. You’ll need it to reset your password. It is shown only now.</p><code class="recovery-code">${esc(recoveryCode)}</code><button class="text-button" data-account-action="dismiss-recovery">I’ve saved my code</button></section>`:''}<div class="practice-layout"><section class="card"><div class="section-head"><h2>${esc(account.user.name)}</h2><span class="pill">${account.user.provider==='google'?'Google account':'Email account'}</span></div><p class="muted">${esc(account.user.email)}</p><div class="notice"><strong>${esc(sync.status)}</strong><p>Assignments, completion progress, grades, and your daily time budget sync automatically. Study timers and practice notes stay on this device.</p></div>${sync.conflict?'<p class="form-error">Another device has a different version of your plan. Choose the version you want to keep. Your local copy stays saved until you choose.</p><div class="timer-controls"><button class="button secondary" data-account-action="cloud">Use cloud plan</button><button class="button" data-account-action="local">Keep this device’s plan</button></div>':'<button class="button secondary" data-account-action="retry">Sync now</button>'}<p id="account-error" role="alert" class="form-error"></p><button class="text-button" data-account-action="logout">Log out</button><details style="margin-top:28px"><summary class="muted">Delete my account</summary><p class="form-error">This permanently deletes this account and all of its cloud assignments and grades. This cannot be undone. Your separate guest plan stays on this device.</p><form id="delete-account-form"><label>Confirm your account email<input name="email" type="email" required autocomplete="off"></label><label>Type DELETE to confirm<input name="confirmation" required pattern="DELETE" autocomplete="off"></label><button class="button secondary" type="submit">Permanently delete my account</button></form></details></section><section class="card"><h2>Bring your guest plan along</h2><p class="muted">If you used StudyFlow on this browser before signing in, you can merge those assignments and grades into this account. Existing records with the same ID stay as they are in your account.</p><button class="button secondary" data-account-action="import" ${!sync.loaded||sync.conflict?'disabled':''}>Import this browser’s guest plan</button><p class="muted">Your cloud plan is checked every 30 seconds and when you return to this tab. Offline changes retry when you reconnect.</p></section></div>`;}
function gradesPage(){const subjects=[...new Set([...(typeof setupSuggestedSubjects==='function'?setupSuggestedSubjects():[]),...assignments.map(a=>a.subject),...grades.map(g=>g.subject)])].sort();const edit=grades.find(g=>g.id===editGradeId);return heading('A CLEARER PICTURE','Your grades, in perspective.','A place to reflect on what’s going well and what to work on next.')+`<div class="grades-layout"><div><div class="subject-grid">${subjects.map(subject=>{const items=grades.filter(g=>g.subject===subject);const avg=weightedGradeAverage(items);return `<section class="card subject-card"><div class="section-head"><h2>${esc(subject)}</h2><span class="subject">${items.length} ${items.length===1?'grade':'grades'}</span></div><strong class="grade-average">${avg===null?'—':avg.toFixed(1)+'<small>%</small>'}</strong><p class="muted">${items.length?'Weighted average':'No grades recorded yet'}</p>${avg!==null?`<meter min="0" max="100" value="${avg}" aria-label="${esc(subject)} average ${avg.toFixed(1)} percent"></meter>`:''}</section>`;}).join('')||'<section class="card empty">Add your first grade to start a subject overview.</section>'}</div><section class="card" style="margin-top:22px"><div class="section-head"><h2>Your grade history</h2><span class="pill">${grades.length} results</span></div>${grades.length?[...grades].sort((a,b)=>b.date.localeCompare(a.date)).map(g=>`<div class="grade-row"><div><strong>${esc(g.name)}</strong><div class="task-meta"><span class="subject">${esc(g.subject)}</span><span>${esc(g.date)} · Weight ${g.weight}</span></div></div><div class="grade-result"><strong>${g.score} / ${g.max}</strong><small>${(g.score/g.max*100).toFixed(1)}%</small><div class="entry-actions"><button class="text-button" data-edit-grade="${esc(g.id)}">Edit</button><button class="text-button delete-control" data-delete-grade="${esc(g.id)}" aria-label="Delete grade ${esc(g.name)}">Delete</button></div></div></div>`).join(''):'<p class="empty">Your results will appear here. Your grades are only one part of your progress.</p>'}<p class="muted">Averages use each result’s percentage × its weight. They are personal tracking estimates; your school may calculate grades differently.</p></section></div><section class="card grade-form-card"><p class="eyebrow">A MOMENT TO REFLECT</p><h2>${edit?'Edit result':'Record a grade'}</h2><form id="grade-form"><label>Subject<input name="subject" list="grade-subjects" maxlength="40" required placeholder="e.g. Math" value="${esc(edit?.subject||'')}"><datalist id="grade-subjects">${subjects.map(s=>`<option value="${esc(s)}">`).join('')}</datalist></label><label>Assessment name<input name="name" maxlength="120" required placeholder="e.g. Algebra quiz" value="${esc(edit?.name||'')}"></label><div class="form-grid"><label>Points earned<input name="score" type="number" step="0.01" min="0" max="10000" required value="${edit?.score??''}"></label><label>Points possible<input name="max" type="number" step="0.01" min="0.01" max="10000" required value="${edit?.max??100}"></label><label>Date<input name="date" type="date" required value="${edit?.date||today}"></label><label>Weight<input name="weight" type="number" step="0.1" min="0.1" max="100" required value="${edit?.weight??1}"></label></div><p class="muted">Use weight 1 for a regular result, or 2 for a result that counts twice.</p><p id="grade-error" role="alert" class="form-error"></p><button class="button" type="submit">${edit?'Save changes':'Save grade'} <span>＋</span></button>${edit?'<button type="button" class="text-button" data-account-action="cancel-grade">Cancel editing</button>':''}</form></section></div>`;}
let googleScriptPromise;
async function setupGoogle(){if(!['login','signup'].includes(page)||isStaticMirror)return;const container=$('#google-button');if(!container)return;if(!authConfig.googleClientId){$('#google-message').textContent='Google sign-in is unavailable. You can continue with email.';return;}try{if(!globalThis.google?.accounts){if(!googleScriptPromise)googleScriptPromise=new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='https://accounts.google.com/gsi/client';s.async=true;s.onload=resolve;s.onerror=()=>reject(new Error('Google could not load. Please use email or try again.'));document.head.appendChild(s);});await googleScriptPromise;}const data=await requestAPI('google-nonce');if(!document.contains(container))return;google.accounts.id.initialize({client_id:authConfig.googleClientId,nonce:data.nonce,auto_select:false,callback:async result=>{if(authBusy)return;authBusy=true;try{const response=await requestAPI('google',{method:'POST',body:JSON.stringify({credential:result.credential})});await enterAccount(response.user,{newAccount:true});}catch(error){if($('#auth-error'))$('#auth-error').textContent=error.message;else toast(error.message);}finally{authBusy=false;}}});google.accounts.id.renderButton(container,{theme:'outline',size:'large',shape:'rectangular',width:Math.min(340,container.clientWidth||300),text:page==='signup'?'signup_with':'signin_with'});}catch(error){if($('#google-message'))$('#google-message').textContent=error.message;}}
globalThis.afterStudyRender=()=>{updateAccountStatus();setupGoogle();};
document.addEventListener('submit',async event=>{if(event.target.id==='delete-account-form'){event.preventDefault();const data=new FormData(event.target);try{await requestAPI('delete-account',{method:'POST',body:JSON.stringify(Object.fromEntries(data))});if(typeof setupKey==='function')localStorage.removeItem(setupKey());for(const k of ['studyflow.assignments.v1','studyflow.grades.v1','studyflow.budget.v1','studyflow.session.v1','pending'])localStorage.removeItem(localKey(k));account.user=null;sync.loaded=false;recoveryCode='';assignments=read('studyflow.assignments.v1',seed());grades=read('studyflow.grades.v1',[]);budget=Number(read('studyflow.budget.v1',90));notes='';questions=[];session={status:'idle',remaining:1500,endsAt:null,task:''};location.hash='#dashboard';render();toast('Your account and cloud plan were deleted.');}catch(error){$('#account-error').textContent=error.message;}return;}if(event.target.id==='grade-form'){event.preventDefault();const data=new FormData(event.target);const result={id:editGradeId||crypto.randomUUID(),subject:data.get('subject').trim(),name:data.get('name').trim(),score:Number(data.get('score')),max:Number(data.get('max')),date:data.get('date'),weight:Number(data.get('weight'))};if(!result.subject||!result.name||!result.date||result.score>result.max||result.score<0||result.max<=0||result.weight<=0){$('#grade-error').textContent='Check the fields. Points earned must be between 0 and points possible.';return;}if(editGradeId)grades=grades.map(g=>g.id===editGradeId?result:g);else grades.push(result);editGradeId=null;save('studyflow.grades.v1',grades);render();toast('Grade saved. Keep the bigger picture in mind.');return;}if(event.target.id!=='auth-form')return;event.preventDefault();if(authBusy)return;const data=new FormData(event.target),mode=page;if(mode!=='login'&&data.get('password')!==data.get('confirm')){$('#auth-error').textContent='Your passwords don’t match yet.';return;}authBusy=true;const button=event.target.querySelector('button[type=submit]');button.disabled=true;button.textContent='Just a moment…';try{const result=await requestAPI(mode==='signup'?'signup':mode==='recover'?'recover':'login',{method:'POST',body:JSON.stringify(Object.fromEntries(data))});recoveryCode=result.recoveryCode||'';await enterAccount(result.user,{newAccount:mode==='signup'});}catch(error){if($('#auth-error'))$('#auth-error').textContent=error.message;else toast(error.message);}finally{authBusy=false;if(document.contains(button)){button.disabled=false;button.textContent=mode==='signup'?'Create account':mode==='recover'?'Reset password':'Log in';}}});
document.addEventListener('click',async event=>{if(event.target.id==='show-password'){const input=$('#auth-password');input.type=input.type==='password'?'text':'password';event.target.textContent=input.type==='password'?'Show':'Hide';event.target.setAttribute('aria-label',input.type==='password'?'Show password':'Hide password');return;}const remove=event.target.closest('[data-delete-grade]');
 if(remove){
   const grade=grades.find(item=>item.id===remove.dataset.deleteGrade);
   if(!grade || !confirm('Delete the grade for “'+grade.name+'”?'))return;
   grades=grades.filter(item=>item.id!==grade.id);
   if(editGradeId===grade.id)editGradeId=null;
   save('studyflow.grades.v1',grades);
   render();
   toast('Grade deleted.');
   return;
 }
 const edit=event.target.closest('[data-edit-grade]');if(edit){editGradeId=edit.dataset.editGrade;render();$('#grade-form input').focus();return;}const target=event.target.closest('[data-account-action]');if(!target)return;target.disabled=true;try{switch(target.dataset.accountAction){case 'dismiss-recovery':recoveryCode='';if(typeof setupPreferences==='function'&&!setupPreferences())location.hash='#setup';render();break;case 'cancel-grade':editGradeId=null;render();break;case 'retry':if(!sync.loaded)await enterAccount(account.user);else if(sync.dirty)await pushPlan();else await pullPlan();render();break;case 'import':{if(!account.user||!sync.loaded||sync.conflict)return;const guest=read('studyflow.assignments.v1',[]),guestGrades=read('studyflow.grades.v1',[]);assignments=[...assignments,...guest.filter(a=>!assignments.some(x=>x.id===a.id))];grades=[...grades,...guestGrades.filter(g=>!grades.some(x=>x.id===g.id))];globalThis.studySyncChanged();await pushPlan();render();toast('Guest plan merged into your account.');break;}case 'cloud':case 'local':{if(sync.busy)return;const cloud=await requestAPI('plan');sync.revision=cloud.revision;sync.conflict=null;if(target.dataset.accountAction==='cloud'){sync.dirty=false;applyPlan(cloud.data);sync.status='All changes synced';}else{sync.dirty=true;await pushPlan();}render();break;}case 'logout':if(sync.busy)throw new Error('Please wait for saving to finish.');if(sync.dirty||sync.conflict)throw new Error('Sync your changes or resolve the conflict before logging out.');await requestAPI('logout',{method:'POST',body:'{}'});account.user=null;sync.loaded=false;recoveryCode='';assignments=read('studyflow.assignments.v1',seed());grades=read('studyflow.grades.v1',[]);budget=Number(read('studyflow.budget.v1',90));session={status:'idle',remaining:1500,endsAt:null,task:''};notes='';questions=[];location.hash='#login';render();toast('Logged out. Your account plan is saved in the cloud.');break;}}catch(error){const errorElement=$('#account-error');if(errorElement)errorElement.textContent=error.message;else toast(error.message);}finally{target.disabled=false;}});
async function initAccount(){const originalHash=location.hash;if(isStaticMirror){account.ready=true;sync.status='Saved on this device';render();return;}try{const [config,me]=await Promise.all([requestAPI('config'),requestAPI('me')]);authConfig=config;account.ready=true;if(me.user){await enterAccount(me.user);location.hash=originalHash||(typeof setupPreferences==='function'&&!setupPreferences()?'#setup':'#dashboard');render();return;}sync.status='Saved on this device';}catch{account.ready=true;sync.status='Saved on this device';}render();}
window.addEventListener('online',()=>{if(sync.dirty)pushPlan();else pullPlan();});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'){if(sync.dirty)pushPlan();else pullPlan();}});
setInterval(()=>{if(sync.dirty)pushPlan();else pullPlan();},30000);
render();initAccount();
